<script setup lang="ts">
import { useI18n } from './i18n'
const { t, tm } = useI18n()
import { onBeforeUnmount, ref, watch } from 'vue'
import { applyCameraRawPreview, type ImageFilter, type PixelImage } from '../shared/image-filters'
import { cameraClipOverlay, cameraScopes, cameraSamplePoint, type CameraGeometry, type CameraMixer } from '../shared/camera-raw-kernels'
const props=defineProps<{url?:string;originalURL?:string;spec:Extract<ImageFilter,{kind:'cameraRaw'}>}>()
const emit=defineEmits<{geometry:[value:CameraGeometry];mixer:[value:CameraMixer]}>()
const canvas=ref<HTMLCanvasElement>(),scope=ref<HTMLCanvasElement>(),view=ref('normal'),scopeMode=ref('histogram'),action=ref<'none'|'point'|'guide'>('none'),error=ref(''),point=ref(0)
let source:PixelImage|undefined,graded:PixelImage|undefined,loadID=0,drag:{x:number;y:number}|undefined,timer:ReturnType<typeof setTimeout>|undefined
// Original asset URLs include their hash; graded PNG URLs are their own version.
// Retain only the current original and preview, sharing concurrent decodes too.
const decodedImages=new Map<string,Promise<PixelImage>>(),scopes=new WeakMap<PixelImage,ReturnType<typeof cameraScopes>>()
function load(url:string):Promise<PixelImage>{const cached=decodedImages.get(url);if(cached){decodedImages.delete(url);decodedImages.set(url,cached);return cached}const pending=new Promise<PixelImage>((resolve,reject)=>{const image=new Image();image.crossOrigin='anonymous';image.onload=()=>{try{const factor=Math.min(1,1024/Math.max(image.naturalWidth,image.naturalHeight)),surface=document.createElement('canvas');surface.width=Math.max(1,Math.round(image.naturalWidth*factor));surface.height=Math.max(1,Math.round(image.naturalHeight*factor));const context=surface.getContext('2d');if(!context)throw Error('Preview surface allocation failed.');context.drawImage(image,0,0,surface.width,surface.height);resolve({width:surface.width,height:surface.height,data:context.getImageData(0,0,surface.width,surface.height).data})}catch(cause){reject(cause)}};image.onerror=()=>reject(Error('Preview image could not be decoded.'));image.src=url});decodedImages.set(url,pending);while(decodedImages.size>2)decodedImages.delete(decodedImages.keys().next().value!);void pending.catch(()=>{if(decodedImages.get(url)===pending)decodedImages.delete(url)});return pending}
async function refresh():Promise<void>{const id=++loadID;try{if(!props.url&&!props.originalURL)return;const [original,preview]=await Promise.all([load(props.originalURL??props.url!),load(props.url??props.originalURL!)]);if(id!==loadID)return;source=original;graded=preview;error.value='';paint()}catch(cause){if(id===loadID)error.value=cause instanceof Error?cause.message:String(cause)}}
function paint():void{if(!graded||!canvas.value)return;let image=graded
  if(source&&view.value==='sharpen')image=applyCameraRawPreview(source,props.spec,{sharpenMask:true})
  else if(source&&view.value==='range')image=applyCameraRawPreview(source,props.spec,{visualizePointColor:point.value})
  else if(view.value==='shadows'||view.value==='highlights'||view.value==='both')image=cameraClipOverlay(graded,view.value!=='highlights',view.value!=='shadows')
  const surface=canvas.value;surface.width=image.width;surface.height=image.height;const context=surface.getContext('2d');if(!context)return;context.putImageData(new ImageData(new Uint8ClampedArray(image.data),image.width,image.height),0,0)
  if(action.value==='guide'&&view.value==='normal'){context.lineWidth=Math.max(1,image.width/512);context.strokeStyle='#19d8ff';for(const guide of props.spec.geometry.guides){context.beginPath();context.moveTo(guide.startX*image.width,guide.startY*image.height);context.lineTo(guide.endX*image.width,guide.endY*image.height);context.stroke()}}
  drawScope(graded)
}
function drawScope(image:PixelImage):void{if(!scope.value)return;let result=scopes.get(image);if(!result){result=cameraScopes(image);scopes.set(image,result)}const surface=scope.value,context=surface.getContext('2d');if(!context)return;surface.width=256;surface.height=128;context.fillStyle='#181818';context.fillRect(0,0,256,128)
  if(scopeMode.value==='histogram'){const peak=Math.max(1,...result.red,...result.green,...result.blue);[result.red,result.green,result.blue].forEach((bins,index)=>{context.strokeStyle=['#f77','#7f7','#79f'][index];context.beginPath();for(let x=0;x<256;x++){const y=127-Math.sqrt(bins[x]/peak)*124;if(x)context.lineTo(x,y);else context.moveTo(x,y)}context.stroke()})}
  else{context.strokeStyle='#555';context.beginPath();context.arc(128,64,61.5,0,Math.PI*2);context.stroke();context.beginPath();context.moveTo(64,64);context.lineTo(192,64);context.moveTo(128,0);context.lineTo(128,128);context.stroke();const peak=Math.max(1,...result.vectorscope);for(let index=0;index<result.vectorscope.length;index++){if(!result.vectorscope[index])continue;const x=index%128,y=Math.floor(index/128),hue=(Math.atan2(y-64,x-64)*180/Math.PI+360)%360;context.fillStyle=`hsla(${hue},80%,65%,${Math.min(1,.2+Math.sqrt(result.vectorscope[index]/peak)*.8)})`;context.fillRect(x+64,y,1,1)}}
}
function position(event:PointerEvent):{x:number;y:number}{const rect=canvas.value!.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(event.clientX-rect.left)/rect.width)),y:Math.max(0,Math.min(1,(event.clientY-rect.top)/rect.height))}}
function down(event:PointerEvent):void{if(action.value==='none'||!source)return;const p=position(event);if(action.value==='point'){const x=Math.min(source.width-1,Math.floor(p.x*source.width)),y=Math.min(source.height-1,Math.floor(p.y*source.height)),at=(y*source.width+x)*4;if(!source.data[at+3]){error.value='Choose a visible image pixel.';return}const points=[...props.spec.mixer.points];if(points.length>=8){error.value='Camera Raw supports up to eight point colors.';return}points.push(cameraSamplePoint([...source.data.slice(at,at+3)]));point.value=points.length-1;emit('mixer',{...props.spec.mixer,points});action.value='none';return}drag=p;canvas.value?.setPointerCapture(event.pointerId)}
function up(event:PointerEvent):void{if(!drag)return;const p=position(event),from=drag;drag=undefined;canvas.value?.releasePointerCapture(event.pointerId);if(Math.hypot(p.x-from.x,p.y-from.y)<.03){error.value='Draw a guide at least 3% of the image length.';return}if(props.spec.geometry.guides.length>=4){error.value='Remove a guide before adding a fifth.';return}emit('geometry',{...props.spec.geometry,upright:'Guided',guides:[...props.spec.geometry.guides,{startX:from.x,startY:from.y,endX:p.x,endY:p.y}]})}
watch(()=>[props.url,props.originalURL],refresh,{immediate:true,flush:'post'})
watch(view,()=>{action.value='none'})
watch([view,scopeMode,action,point],()=>{try{paint()}catch(cause){error.value=cause instanceof Error?cause.message:String(cause)}},{flush:'post'})
watch(()=>props.spec,()=>{clearTimeout(timer);timer=setTimeout(()=>paint(),150)},{deep:true})
onBeforeUnmount(()=>{loadID++;clearTimeout(timer);decodedImages.clear();source=undefined;graded=undefined})
</script>
<template><div class="camera-preview"><div class="camera-preview-image"><canvas ref="canvas" :aria-label="t('Camera Raw preview; click to sample or drag a guide')" :class="{sampling:action !== 'none'}" @pointerdown="down" @pointerup="up" @pointercancel="drag=undefined"/></div>
  <div class="camera-preview-tools"><label>{{ t('Preview') }}<select v-model="view"><option value="normal">{{ t('Image') }}</option><option value="shadows">{{ t('Shadow clipping') }}</option><option value="highlights">{{ t('Highlight clipping') }}</option><option value="both">{{ t('Both clipping overlays') }}</option><option value="sharpen">{{ t('Sharpen mask') }}</option><option value="range" :disabled="!spec.mixer.points.length">{{ t('Point color range') }}</option></select></label><select v-if="view==='range'" v-model.number="point" :aria-label="t('Point color')"><option v-for="(_,index) in spec.mixer.points" :key="index" :value="index">{{t('Point {index}', {index:index+1})}}</option></select>
  <button type="button" :aria-pressed="action==='point'" @click="action=action==='point'?'none':'point'">{{ t('Sample point color') }}</button><button type="button" :aria-pressed="action==='guide'" @click="action=action==='guide'?'none':'guide'">{{ t('Draw geometry guide') }}</button></div>
  <p v-if="action !== 'none'" class="camera-preview-help">{{ t(action==='point'?'Click the image to add a point color from the original pixels.':'Drag along a vertical or horizontal edge to add an Upright guide.') }}</p>
  <label class="camera-scope-label">{{ t('Scope') }}<select v-model="scopeMode"><option value="histogram">{{ t('RGB histogram') }}</option><option value="vectorscope">{{ t('Hue / saturation vectorscope') }}</option></select></label><canvas ref="scope" class="camera-scope" :aria-label="t(scopeMode)"/><p v-if="error" role="alert">{{ tm(error) }}</p>
</div></template>
<style scoped>.camera-preview{min-width:0;display:flex;flex-direction:column;gap:8px}.camera-preview-image{height:min(320px,40vh);display:flex;justify-content:center;align-items:center;overflow:auto;background:#181818}.camera-preview-image canvas{max-width:100%;max-height:100%;object-fit:contain;background:repeating-conic-gradient(#888 0% 25%,#aaa 0% 50%) 0 0/16px 16px}.camera-preview-image canvas.sampling{cursor:crosshair;touch-action:none}.camera-preview-tools{display:flex;flex-wrap:wrap;gap:6px;align-items:center}.camera-preview-tools label,.camera-scope-label{display:flex;gap:8px;align-items:center;font-size:11px}.camera-preview-tools button[aria-pressed=true]{border-color:#1688ff;color:#7fbaff}.camera-preview-tools select,.camera-scope-label select{max-width:180px}.camera-scope{width:100%;height:90px;object-fit:contain;background:#181818}.camera-preview p{font-size:11px;color:#dfb07d;margin:0}.camera-preview .camera-preview-help{color:#aaa}</style>
